class StoreIovsTest : public MultiClientTestFixture {
 protected:
  using Row = std::tuple<uint64_t, std::string, std::string>;

  ////////////////////////////////////////////////////////////////////////////////
  /// @return The name of a new, empty tag
  ////////////////////////////////////////////////////////////////////////////////
  std::string createTag(const std::string &prefix = "store_iovs") {
    const std::string tagName = uniqueTagName(prefix);
    TagDto tag(tagName, "time", "storeIovs test tag");
    // Oracle-backed servers reject an empty payloadSpec (stored as NULL).
    tag.setObjectType("JSON");
    myCrestApi->createTag(tag);
    return tagName;
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Store one JSON payload per entry in a new tag of its own
  /// @return The payload hashes, in the order of datas
  ////////////////////////////////////////////////////////////////////////////////
  std::vector<std::string> storePayloads(
      const std::vector<std::string> &datas) {
    const std::string sourceTag = createTag("store_iovs_source");
    StoreSetDto input;
    uint64_t since = 0;
    for (const auto &data : datas) {
      input.push_back(StoreDto(since++, "", data));
    }
    const StoreSetDto stored =
        myCrestApi->storeData(sourceTag, input, "JSON", "test", "none", "1", 0);
    std::vector<std::string> hashes;
    for (const auto &dto : stored.getResources()) {
      hashes.push_back(dto.getHash());
    }
    return hashes;
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @return Every IOV row of the tag as (since, hash, insertionTime), in
  ///         selectIovs order (the authoritative row first within a since)
  ////////////////////////////////////////////////////////////////////////////////
  std::vector<Row> rows(const std::string &tagName) {
    // The file storage always puts the newest row first within a since and
    // accepts no secondary sort key. The server needs it spelled out.
    const std::string sort =
        isServer() ? "id.since:ASC,id.insertionTime:DESC" : "id.since:ASC";
    const IovSetDto iovs =
        myCrestApi->selectIovs(tagName, 0, -1, 0, 1000, 0, sort);
    std::vector<Row> result;
    for (const auto &iov : iovs.getResources()) {
      result.emplace_back(iov.getSince(), iov.getPayloadHash(),
                          iov.getInsertionTime().value_or(""));
    }
    return result;
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @return An IovSetDto of one IOV per (since, hash) pair, all for tagName
  ////////////////////////////////////////////////////////////////////////////////
  static IovSetDto iovSet(
      const std::string &tagName,
      const std::vector<std::pair<uint64_t, std::string>> &pairs) {
    IovSetDto set;
    for (const auto &[since, hash] : pairs) {
      set.push_back(IovDto(tagName, since, hash));
    }
    return set;
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  On the server, sleep past the current second before a since is
  ///         stored again. Oracle keys IOVs on (tag, since, insertion time) at
  ///         1 s resolution, so a second write within the same second fails
  ///         with ORA-00001. The file storage keeps writing back to back.
  ////////////////////////////////////////////////////////////////////////////////
  void waitBeforeRestoringSince() const {
    if (isServer()) {
      std::this_thread::sleep_for(std::chrono::milliseconds(1100));
    }
  }

  bool isServer() const { return storage == "CrestServer"; }
}

