TEST_P(StoreIovsTest, StoresIovsForExistingPayloads) {
  const auto hashes = storePayloads({"payload a", "payload b"});
  const std::string tagName = createTag();

  const IovSetDto stored = myCrestApi->storeIovs(
      iovSet(tagName, {{10, hashes[0]}, {20, hashes[1]}}));

  ASSERT_EQ(stored.size(), 2u);
  const std::vector<std::pair<uint64_t, std::string>> expected = {
      {10, hashes[0]}, {20, hashes[1]}};
  for (std::size_t i = 0; i < expected.size(); ++i) {
    const IovDto &iov = stored.getResources()[i];
    EXPECT_EQ(iov.getTagName(), tagName);
    EXPECT_EQ(iov.getSince(), expected[i].first);
    EXPECT_EQ(iov.getPayloadHash(), expected[i].second);
    EXPECT_FALSE(iov.getInsertionTime().value_or("").empty());
  }
  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<0>(storedRows[0]), 10u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hashes[0]);
  EXPECT_EQ(std::get<0>(storedRows[1]), 20u);
  EXPECT_EQ(std::get<1>(storedRows[1]), hashes[1]);
}

TEST_P(StoreIovsTest, SameSinceNewHashOverrides) {
  const auto hashes = storePayloads({"original", "override"});
  const std::string tagName = createTag();

  myCrestApi->storeIovs(iovSet(tagName, {{100, hashes[0]}}));
  waitBeforeRestoringSince();
  myCrestApi->storeIovs(iovSet(tagName, {{100, hashes[1]}}));

  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<0>(storedRows[0]), 100u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hashes[1]);
}

TEST_P(StoreIovsTest, StoreDataThenStoreIovsKeepsBoth) {
  const auto hashes = storePayloads({"stored by storeIovs"});
  const std::string tagName = createTag();
  StoreSetDto input;
  input.push_back(StoreDto(1, "", "stored by storeData"));
  myCrestApi->storeData(tagName, input, "JSON", "test", "none", "1", 0);

  myCrestApi->storeIovs(iovSet(tagName, {{2, hashes[0]}}));

  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<0>(storedRows[0]), 1u);
  EXPECT_EQ(std::get<0>(storedRows[1]), 2u);
}

TEST_P(StoreIovsTest, EmptySetThrows) {
  EXPECT_THROW(myCrestApi->storeIovs(IovSetDto()), CrestException);
}

TEST_P(StoreIovsTest, MissingTagThrows) {
  const auto hashes = storePayloads({"payload for a missing tag"});
  const std::string tagName = uniqueTagName("store_iovs_missing");

  EXPECT_THROW(myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[0]}})),
               CrestException);

  // Nothing is left pending for the missing tag: the next write's flush must
  // not create its iovs.json.
  const std::string existing = createTag();
  EXPECT_NO_THROW(myCrestApi->storeIovs(iovSet(existing, {{1, hashes[0]}})));
  EXPECT_EQ(rows(existing).size(), 1u);
  if (!isServer()) {
    EXPECT_FALSE(std::filesystem::exists(connectionString + "/tags/" + tagName +
                                         "/iovs.json"));
  }
}

TEST_P(StoreIovsTest, UnknownHashThrowsAndWritesNothing) {
  const auto hashes = storePayloads({"known payload"});
  const std::string tagName = createTag();
  myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[0]}}));
  const auto before = rows(tagName);
  const std::string unknown =
      CrestApiBase::getHash("payload that was never stored");

  EXPECT_THROW(myCrestApi->storeIovs(iovSet(tagName, {{2, unknown}})),
               CrestException);
  EXPECT_EQ(rows(tagName), before);

  // Inside a batch, after a valid IOV. The server isn't transactional, so it
  // may keep the first one.
  EXPECT_THROW(
      myCrestApi->storeIovs(iovSet(tagName, {{3, hashes[0]}, {4, unknown}})),
      CrestException);
  if (!isServer()) {
    EXPECT_EQ(rows(tagName), before);
  }
}

TEST_P(StoreIovsTest, RestoringAnExistingIovMakesItNewest) {
  const auto hashes = storePayloads({"payload a", "payload b"});
  const std::string tagName = createTag();
  myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[0]}}));
  waitBeforeRestoringSince();
  myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[1]}}));
  ASSERT_EQ(std::get<1>(rows(tagName).at(0)), hashes[1]);

  waitBeforeRestoringSince();
  const IovSetDto echoed =
      myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[0]}}));

  ASSERT_EQ(echoed.size(), 1u);
  EXPECT_EQ(echoed.getResources()[0].getPayloadHash(), hashes[0]);
  EXPECT_FALSE(
      echoed.getResources()[0].getInsertionTime().value_or("").empty());
  auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hashes[0]);
  EXPECT_EQ(std::get<1>(storedRows[1]), hashes[1]);

  // Re-storing the newest IOV keeps it newest.
  waitBeforeRestoringSince();
  myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[0]}}));
  storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hashes[0]);
  EXPECT_EQ(std::get<1>(storedRows[1]), hashes[1]);
}

TEST_P(StoreIovsTest, RepeatedIovInBatchIsStoredOnce) {
  const auto hashes = storePayloads({"payload a", "payload b"});
  const std::string tagName = createTag();

  const IovSetDto echoed = myCrestApi->storeIovs(
      iovSet(tagName, {{2, hashes[1]}, {5, hashes[0]}, {5, hashes[0]}}));

  EXPECT_EQ(echoed.size(), 3u);
  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<0>(storedRows[0]), 2u);
  EXPECT_EQ(std::get<0>(storedRows[1]), 5u);
}

TEST_P(StoreIovsTest, FsRejectsMixedTags) {
  if (isServer()) {
    GTEST_SKIP() << "the server stores each IOV in its own tag";
  }
  const auto hashes = storePayloads({"mixed tags payload"});
  const std::string first = createTag();
  const std::string second = createTag();
  IovSetDto set = iovSet(first, {{1, hashes[0]}});
  set.push_back(IovDto(second, 2, hashes[0]));

  EXPECT_THROW(myCrestApi->storeIovs(set), CrestException);
  EXPECT_TRUE(rows(first).empty());
  EXPECT_TRUE(rows(second).empty());
}

TEST_P(StoreIovsTest, FsRejectsMalformedHashes) {
  if (isServer()) {
    GTEST_SKIP() << "the hash check guards file storage paths";
  }
  const std::string valid = storePayloads({"malformed hash test"})[0];
  const std::string tagName = createTag();
  const std::string dataFolder = connectionString + "/data";
  const auto entriesBefore =
      std::distance(std::filesystem::directory_iterator(dataFolder), {});
  std::string upper = valid;
  upper[0] = 'A';

  // The last one resolves to the stored payload's payload.json, so only the
  // format check rejects it.
  for (const std::string &hash :
       {std::string("../x"), valid.substr(0, 63), valid + "0", upper,
        std::string("abc/") + valid.substr(4), valid + "/../" + valid}) {
    EXPECT_THROW(myCrestApi->storeIovs(iovSet(tagName, {{1, hash}})),
                 CrestException)
        << hash;
  }
  EXPECT_TRUE(rows(tagName).empty());
  EXPECT_EQ(std::distance(std::filesystem::directory_iterator(dataFolder), {}),
            entriesBefore);
}

TEST_P(StoreIovsTest, FsAcceptsTriggerDbHashWithoutPayload) {
  if (isServer()) {
    GTEST_SKIP() << "file storage check";
  }
  const std::string tagName = createTag();
  const std::string hash = "triggerdb://smk/1234";

  myCrestApi->storeIovs(iovSet(tagName, {{7, hash}}));

  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 1u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hash);
}

TEST_P(StoreIovsTest, FsFreshClientAppendsToExistingIovs) {
  if (isServer()) {
    GTEST_SKIP() << "the server keeps no client-side IOV state";
  }
  const auto hashes = storePayloads({"payload a", "payload b"});
  const std::string tagName = createTag();
  myCrestApi->storeIovs(iovSet(tagName, {{1, hashes[0]}}));

  // A client in another process, with nothing in memory yet.
  CrestApiFs fresh(true, connectionString);
  fresh.storeIovs(iovSet(tagName, {{2, hashes[1]}}));

  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 2u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hashes[0]);
  EXPECT_EQ(std::get<1>(storedRows[1]), hashes[1]);
}

TEST_P(StoreIovsTest, FsWorksWithoutRewriteMode) {
  if (isServer()) {
    GTEST_SKIP() << "rewrite mode is a file storage setting";
  }
  const auto hashes = storePayloads({"non-rewrite payload"});
  const std::string tagName = createTag();

  CrestApiFs noRewrite(false, connectionString);
  noRewrite.storeIovs(iovSet(tagName, {{3, hashes[0]}}));

  const auto storedRows = rows(tagName);
  ASSERT_EQ(storedRows.size(), 1u);
  EXPECT_EQ(std::get<1>(storedRows[0]), hashes[0]);
}
